// A Statement of Account for one person's utang, and the one line reminder
// that goes with it. Ported 1:1 from mobile/lib/statement.js and golden locked
// against text generated by EXECUTING that file, byte for byte.
//
// This is a document someone hands to a friend, so the numbers have to tie
// out in front of both of them: total lent minus total paid equals what is
// still open, with nothing forecast and nothing inferred. Everything here
// only sums what is already stored.
//
// It shares the whole peso formatter with the debt SOA (formatMoneyText),
// which is the RN formatter, not the app's on-screen one. Shared text has
// always been formatted that way here, and a statement is shared text.
//
// The two emoji in the closing lines are deliberate and stay. Salapify's icon
// rule is about glyphs the app DRAWS, which the palette owns; this is plain
// text landing in someone's chat app, where the app's palette does not reach
// and a Material icon cannot be typed.

import 'debtmath.dart' show formatMoneyText;
import 'transfers.dart' show jsNumber;

const _months = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
];

/// JS `Number(x)`, with anything not finite folded to 0, exactly as
/// statement.js does before it adds a value to a total. A junk amount in a
/// hand edited backup contributes nothing rather than turning a whole
/// statement into NaN.
double _num(dynamic x) {
  if (x == null) return 0;
  if (x == true) return 1;
  if (x == false) return 0;
  if (x is num) return x.isFinite ? x.toDouble() : 0;
  if (x is String) {
    final v = jsNumber(x);
    return v.isFinite ? v : 0;
  }
  return 0;
}

/// JS truthiness for the `||` fallbacks the original leans on.
bool _falsy(dynamic v) =>
    v == null || v == false || v == '' || (v is num && (v == 0 || v.isNaN));

/// A trimmed string, or null when the value is not a non-empty string. Mirrors
/// `typeof x === 'string' && x.trim()`, so a name of 42 and a name of "  "
/// both fall through to the default.
String? _text(dynamic v) {
  if (v is! String) return null;
  final t = v.trim();
  return t.isEmpty ? null : t;
}

/// 'YYYY-MM-DD' to 'Jul 8, 2026'. Junk, empty, or a month outside 01 to 12
/// returns '', which is how the caller decides to print "No due date".
String fmtDate(dynamic iso) {
  final s = _falsy(iso) ? '' : iso.toString();
  final m = RegExp(r'^(\d{4})-(\d{2})-(\d{2})$').firstMatch(s);
  if (m == null) return '';
  final monthIndex = int.parse(m.group(2)!) - 1;
  if (monthIndex < 0 || monthIndex >= _months.length) return '';
  return '${_months[monthIndex]} ${int.parse(m.group(3)!)}, ${m.group(1)}';
}

class _Copy {
  final String forWhom,
      asOf,
      utang,
      due,
      noDue,
      utangDefault,
      paidTag,
      ofPaid,
      markedPaid,
      totalLent,
      payHead,
      totalPaid,
      stillOpen,
      fullyPaid,
      closeOpen,
      closePaid;
  const _Copy({
    required this.forWhom,
    required this.asOf,
    required this.utang,
    required this.due,
    required this.noDue,
    required this.utangDefault,
    required this.paidTag,
    required this.ofPaid,
    required this.markedPaid,
    required this.totalLent,
    required this.payHead,
    required this.totalPaid,
    required this.stillOpen,
    required this.fullyPaid,
    required this.closeOpen,
    required this.closePaid,
  });
}

const _en = _Copy(
  forWhom: 'For',
  asOf: 'As of',
  utang: 'UTANG',
  due: 'Due',
  noDue: 'No due date',
  utangDefault: 'Utang',
  paidTag: 'paid',
  ofPaid: 'of',
  markedPaid: 'Marked paid',
  totalLent: 'Total lent',
  payHead: 'PAYMENTS RECEIVED',
  totalPaid: 'Total paid',
  stillOpen: 'STILL OPEN',
  fullyPaid: 'FULLY PAID',
  closeOpen:
      'No pressure at all, this is just my own record so we are both on '
      'the same page. Salamat!',
  closePaid: 'Fully paid na, salamat! Keeping this just for our record. 🙌',
);

const _tl = _Copy(
  forWhom: 'Para kay',
  asOf: 'As of',
  utang: 'UTANG',
  due: 'Due',
  noDue: 'Walang due date',
  utangDefault: 'Utang',
  paidTag: 'bayad na',
  ofPaid: 'ng',
  markedPaid: 'Minarkahang bayad',
  totalLent: 'Kabuuang inutang',
  payHead: 'MGA NABAYARAN NA',
  totalPaid: 'Kabuuang bayad',
  stillOpen: 'NATITIRA',
  fullyPaid: 'BAYAD NA LAHAT',
  closeOpen:
      'Walang pressure ha, record ko lang ito para malinaw sa ating '
      'dalawa. Salamat!',
  closePaid: 'Bayad na lahat, salamat! Record lang natin ito. 🙌',
);

/// The language a statement or reminder is written in. The picker that offers
/// it is English, and so is everything inside the app; this choice is about a
/// message the user SENDS to someone else, in whichever language they two
/// actually talk in.
enum StatementLang { en, tl }

_Copy _copy(StatementLang lang) => lang == StatementLang.tl ? _tl : _en;

class _PayLine {
  final dynamic date;
  final double amount;
  final bool marked;
  final String note;
  const _PayLine(this.date, this.amount, {this.marked = false, this.note = ''});
}

/// The statement as one plain text block, ready for a share sheet.
///
/// The reconciliation honours the receivable's `paid` flag exactly like the
/// ledger does: a paid utang counts as fully settled even when it carries no
/// logged payments, because someone can mark cash paid without logging it and
/// legacy utang were settled before payment tracking existed. That keeps
/// STILL OPEN equal to what the app shows as owed, so a statement can never
/// bill a friend for money the app itself considers paid.
String buildPersonStatement(
  Map<String, dynamic>? person,
  dynamic receivables, {
  StatementLang lang = StatementLang.en,
  required DateTime asOf,
}) {
  final t = _copy(lang);
  final name = _text(person?['name']) ?? 'Someone';
  final list = receivables is List
      ? receivables.whereType<Map>().map((r) => r.cast<String, dynamic>())
      : const <Map<String, dynamic>>[];

  var totalLent = 0.0;
  final utangLines = <String>[];
  final payments = <_PayLine>[];
  for (final r in list) {
    final amount = _num(r['amount']);
    totalLent += amount;
    var loggedSum = 0.0;
    for (final p in (r['payments'] as List? ?? []).whereType<Map>()) {
      final pa = _num(p['amount']);
      loggedSum += pa;
      payments.add(_PayLine(_falsy(p['date']) ? '' : p['date'], pa));
    }
    final isPaid = r['paid'] == true;
    final label = _text(r['note']) ?? t.utangDefault;
    // A paid utang whose logged payments fall short was settled by marking it
    // paid; record that difference so the payment lines still sum to the
    // total paid line directly under them.
    if (isPaid && amount - loggedSum > 0.005) {
      payments.add(_PayLine('', amount - loggedSum, marked: true, note: label));
    }
    final due = fmtDate(r['dueDate']);
    final status = isPaid
        ? ' · ${t.paidTag}'
        : loggedSum > 0.005
        ? ' · ${formatMoneyText(loggedSum)} ${t.ofPaid} '
              '${formatMoneyText(amount)} ${t.paidTag}'
        : '';
    utangLines.add(
      '${due.isNotEmpty ? '${t.due} $due' : t.noDue}   $label   '
      '${formatMoneyText(amount)}$status',
    );
  }
  final totalPaid = payments.fold(0.0, (s, e) => s + e.amount);
  final open = (((totalLent - totalPaid) * 100) + 0.5).floorToDouble() / 100;
  final stillOpen = open > 0 ? open : 0.0;
  final fullyPaid = totalLent > 0 && stillOpen <= 0.005;

  // Oldest first; the marked paid lines, which carry no date, come last.
  // Decorated with the original index because JS sort is stable and Dart's is
  // not, and two payments made on the same day would otherwise swap places
  // between the two apps for no reason a reader could explain.
  final indexed = [for (var i = 0; i < payments.length; i++) (i, payments[i])];
  indexed.sort((ea, eb) {
    final a = ea.$2, b = eb.$2;
    final aEmpty = a.date == '', bEmpty = b.date == '';
    if (aEmpty && !bEmpty) return 1;
    if (!aEmpty && bEmpty) return -1;
    if (a.date is String && b.date is String) {
      final c = (a.date as String).compareTo(b.date as String);
      if (c != 0) return c < 0 ? -1 : 1;
    }
    // A date that is not a string compares NaN both ways in JS, which is
    // neither less nor greater, so the original order stands.
    return ea.$1.compareTo(eb.$1);
  });

  final asOfStr = fmtDate(
    '${asOf.year.toString().padLeft(4, '0')}-'
    '${asOf.month.toString().padLeft(2, '0')}-'
    '${asOf.day.toString().padLeft(2, '0')}',
  );

  final lines = <String>[
    'SALAPIFY · Statement of Account',
    '${t.forWhom}: $name',
    '${t.asOf} $asOfStr',
    '',
    t.utang,
    ...utangLines,
    '${t.totalLent}: ${formatMoneyText(totalLent)}',
  ];
  if (indexed.isNotEmpty) {
    lines.addAll(['', t.payHead]);
    for (final (_, e) in indexed) {
      if (e.marked) {
        lines.add('${t.markedPaid}   ${e.note}   ${formatMoneyText(e.amount)}');
      } else {
        lines.add('${fmtDate(e.date)}   ${formatMoneyText(e.amount)}'.trim());
      }
    }
    lines.add('${t.totalPaid}: ${formatMoneyText(totalPaid)}');
  }

  lines.add('');
  if (fullyPaid) {
    lines.addAll([t.fullyPaid, '', t.closePaid]);
  } else {
    lines.addAll([
      '${t.stillOpen}: ${formatMoneyText(stillOpen)}',
      '',
      t.closeOpen,
    ]);
  }
  lines.add('Made with Salapify.');
  return lines.join('\n');
}

/// A one line reminder covering everything a person still owes, warm and
/// never a demand. The tone is the founder's rule: this app helps people ask
/// without it costing them the friendship.
String buildPersonReminder(
  Map<String, dynamic>? person,
  dynamic owed, {
  StatementLang lang = StatementLang.en,
}) {
  final name = _text(person?['name']) ?? 'Someone';
  final amount = formatMoneyText(_num(owed));
  if (lang == StatementLang.tl) {
    return 'Hi $name! Paalala lang sa $amount na total ng utang. Walang '
        'pressure, para lang di natin makalimutan. Salamat! 🙏';
  }
  return 'Hi $name! Friendly reminder about the $amount total you still owe. '
      'No rush, just so we both remember. Thank you! 🙏';
}
